import{_ as i,o as n,c as a,ai as l}from"./chunks/framework.BxxKhjs3.js";const c=JSON.parse('{"title":"20-嵌套函数和函数调用","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/20-嵌套函数和函数调用/20-嵌套函数和函数调用.md","filePath":"仓颉入门到实战/20-嵌套函数和函数调用/20-嵌套函数和函数调用.md","lastUpdated":1734914353000,"__rawMarkdown":"# 20-嵌套函数和函数调用\\n\\n# 嵌套函数\\n\\n定义在源文件顶层的函数被称为全局函数。定义在函数体内的函数被称为嵌套函数。\\n\\n示例，函数 `foo` 内定义了一个嵌套函数 `nestAdd`，可以在 `foo` 内调用该嵌套函数 `nestAdd`，也可以将嵌套函数 `nestAdd` 作为返回值返回，在 `foo` 外对其进行调用：\\n\\n```javascript\\nfunc foo() {\\n    func nestAdd(a: Int64, b: Int64) {\\n        a + b + 3\\n    }\\n\\n    println(nestAdd(1, 2))  // 6\\n\\n    return nestAdd\\n}\\n\\nmain() {\\n    let f = foo()\\n    let x = f(1, 2)\\n    println(\\"result: ${x}\\")\\n}\\n```\\n\\n程序会输出：\\n\\n```javascript\\n6;\\nresult: 6;\\n```\\n\\n# 嵌套函数\\n\\n定义在源文件顶层的函数被称为全局函数。定义在函数体内的函数被称为嵌套函数。\\n\\n示例，函数 `foo` 内定义了一个嵌套函数 `nestAdd`，可以在 `foo` 内调用该嵌套函数 `nestAdd`，也可以将嵌套函数 `nestAdd` 作为返回值返回，在 `foo` 外对其进行调用：\\n\\n```javascript\\nfunc foo() {\\n    func nestAdd(a: Int64, b: Int64) {\\n        a + b + 3\\n    }\\n\\n    println(nestAdd(1, 2))  // 6\\n\\n    return nestAdd\\n}\\n\\nmain() {\\n    let f = foo()\\n    let x = f(1, 2)\\n    println(\\"result: ${x}\\")\\n}\\n```\\n\\n程序会输出：\\n\\n```javascript\\n6;\\nresult: 6;\\n```\\n"}'),p={name:"仓颉入门到实战/20-嵌套函数和函数调用/20-嵌套函数和函数调用.md"};function e(t,s,h,k,r,d){return n(),a("div",null,[...s[0]||(s[0]=[l("",13)])])}const o=i(p,[["render",e]]);export{c as __pageData,o as default};
